// src/pages/Home.jsx
import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { useUI } from "../context/UIContext";
import Input from "../components/common/Input";
import Button from "../components/common/Button";
import styles from "../Home.module.css";
import eveVideo from "../assets/eve_sdm_talk.mp4";
import { introText } from "../constants/sdm";

const Home = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [formData, setFormData] = useState({ userName: "", birthday: "" });
  const [pureSpeechText, setPureSpeechText] = useState("");
  const [currentSubtitle, setCurrentSubtitle] = useState("");

  useEffect(() => {
    // 保留此設定，同時配合 CSS 的強效覆蓋來隱藏頭像
    setHeroData(null);

    const cleanedText = introText.replace(/<[^>]*>/g, "").trim();
    setPureSpeechText(cleanedText);

    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [setHeroData]);

  const handlePlaySpeech = (text) => {
    if (!window.speechSynthesis || !videoRef.current || !text) return;

    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "zh-TW";
    utterance.rate = 1.0;

    utterance.onstart = () => {
      setIsPlaying(true);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.muted = true;
        videoRef.current.play().catch((err) => console.log(err));
      }
    };

    utterance.onboundary = (event) => {
      const currentIndex = event.charIndex;
      // 每次截取當前字元往後 22 個字，實現動態滾動字幕
      const subtitleChunk = text.substring(currentIndex, currentIndex + 22);
      setCurrentSubtitle(subtitleChunk);
    };

    utterance.onend = () => {
      setIsPlaying(false);
      setIsPaused(false);
      setCurrentSubtitle("");
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0;
      }
    };

    utterance.onerror = () => {
      setIsPlaying(false);
      setIsPaused(false);
      setCurrentSubtitle("");
      if (videoRef.current) videoRef.current.pause();
    };

    window.speechSynthesis.speak(utterance);
  };

  const handleTogglePlay = (e) => {
    e.stopPropagation();

    if (!window.speechSynthesis) return;

    if (isPlaying && !isPaused) {
      window.speechSynthesis.pause();
      if (videoRef.current) videoRef.current.pause();
      setIsPaused(true);
    } else if (isPlaying && isPaused) {
      window.speechSynthesis.resume();
      if (videoRef.current) {
        videoRef.current.play().catch((err) => console.log(err));
      }
      setIsPaused(false);
    } else {
      handlePlaySpeech(pureSpeechText);
    }
  };

  const handleStart = () => {
    if (!formData.userName || !formData.birthday) {
      alert("請填寫完整資料後再開始");
      return;
    }
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    if (videoRef.current) videoRef.current.pause();

    setAllAnswers((prev) => ({
      ...prev,
      userName: formData.userName,
      birthday: formData.birthday,
    }));
    navigate("/selection");
  };

  return (
    <div className={styles.pageContainer}>
      <div className={styles.interactiveCard}>
        {/* 上半部影片與控制區 */}
        <div className={styles.videoSection}>
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            webkit-playsinline="true"
            preload="auto"
            loop
            className={styles.theatreVideo}
          />

          {/* 🌟 電影院字幕區：此時徹底獨佔底部空間，絕不被按鈕擋住 */}
          {isPlaying && currentSubtitle && (
            <div className={styles.subtitleOverlay}>
              <p className={styles.subtitleText}>{currentSubtitle}</p>
            </div>
          )}

          {/* 左上角狀態燈 */}
          {isPlaying && (
            <div className={styles.audioBadge}>
              <span
                className={isPaused ? styles.audioDotPaused : styles.audioDot}
              ></span>
              {isPaused ? "已暫停" : "說明中..."}
            </div>
          )}

          {/* 🌟 移至右上方的小巧控制按鈕 */}
          <button
            className={styles.controlBtnTopRight}
            onClick={handleTogglePlay}
          >
            {isPlaying && !isPaused ? "⏸ 暫停" : "▶️ 播放"}
          </button>
        </div>

        {/* 下半部表單內容 */}
        <div className={styles.contentSection}>
          <div className={styles.inputWrapper}>
            <Input
              label="請輸入您的姓名"
              name="userName"
              value={formData.userName}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, userName: e.target.value }))
              }
            />
            <Input
              label="請輸入您的出生年月日"
              type="date"
              name="birthday"
              value={formData.birthday}
              onChange={(e) =>
                setFormData((prev) => ({ ...prev, birthday: e.target.value }))
              }
            />
          </div>

          <div className={styles.buttonWrapper}>
            <Button onClick={handleStart} fullWidth>
              開始使用 ➔
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
